import pytest
from requests.exceptions import RequestException

@pytest.mark.parametrize("pet_id, additional_metadata, file_path, expected_status", [
    (1, "Sample metadata", "tests/test_data/sample_image.jpg", 200),  # Happy path
    (1, None, "tests/test_data/sample_image.jpg", 200),              # Without metadata
    (99999, "Sample metadata", "tests/test_data/sample_image.jpg", 404),  # Pet not found
    (1, "Sample metadata", None, 400),                               # No file uploaded
    (1, None, "non_existing_file.jpg", 400),                         # Invalid file path
])
def test_upload_pet_image(api_client, valid_api_key, schema_validator, pet_id, additional_metadata, file_path, expected_status):
    """
    Test the /pet/{petId}/uploadImage endpoint with various scenarios.
    """
    endpoint = f"pet/{pet_id}/uploadImage"
    headers = {
        "Authorization": f"Bearer {valid_api_key}"
    }
    params = {
        "additionalMetadata": additional_metadata
    }
    files = None
    
    if file_path:
        try:
            files = {"file": open(file_path, "rb")}
        except FileNotFoundError:
            files = None

    try:
        response = api_client.helper.make_request(
            endpoint=endpoint,
            method="POST",
            params=params,
            headers=headers,
            files=files
        )
    except RequestException as e:
        pytest.fail(f"Request failed: {e}")

    # Assertions based on expected status
    assert response.status_code == expected_status, f"Expected {expected_status} but got {response.status_code}"

    if expected_status == 200:
        # Validate response JSON schema
        response_json = response.json()
        assert schema_validator.validate_api_response_schema(response_json), "Response schema validation failed"
        assert response_json["code"] == 200  # Example validation
        assert "message" in response_json, "Response should include 'message'"
    elif expected_status == 404:
        assert response.json().get("message") == "Pet not found"

